// Replaces the `mime-types` package, which requires Node's `path` module and so
// cannot load on Obsidian mobile. Only covers extensions Obsidian accepts as
// vault attachments; anything else falls back to a generic binary type.
const MIME_TYPES_BY_EXTENSION: Record<string, string> = {
  // Images
  avif: "image/avif",
  bmp: "image/bmp",
  gif: "image/gif",
  ico: "image/vnd.microsoft.icon",
  jpeg: "image/jpeg",
  jpg: "image/jpeg",
  png: "image/png",
  svg: "image/svg+xml",
  tif: "image/tiff",
  tiff: "image/tiff",
  webp: "image/webp",
  // Audio
  aac: "audio/aac",
  flac: "audio/flac",
  m4a: "audio/mp4",
  mp3: "audio/mpeg",
  oga: "audio/ogg",
  ogg: "audio/ogg",
  wav: "audio/wav",
  // Video
  mkv: "video/x-matroska",
  mov: "video/quicktime",
  mp4: "video/mp4",
  ogv: "video/ogg",
  webm: "video/webm",
  // Documents
  pdf: "application/pdf",
  // Text
  canvas: "application/json",
  css: "text/css",
  csv: "text/csv",
  html: "text/html",
  js: "text/javascript",
  json: "application/json",
  md: "text/markdown",
  txt: "text/plain",
  xml: "text/xml",
  yaml: "text/yaml",
  yml: "text/yaml",
};

export const DEFAULT_MIME_TYPE = "application/octet-stream";

export const getMimeTypeForPath = (filePath: string): string => {
  const fileName = filePath.split("/").pop() ?? "";
  const lastDotIndex = fileName.lastIndexOf(".");
  // A leading dot is a dotfile, not an extension.
  if (lastDotIndex <= 0) return DEFAULT_MIME_TYPE;
  const extension = fileName.slice(lastDotIndex + 1).toLowerCase();
  return MIME_TYPES_BY_EXTENSION[extension] ?? DEFAULT_MIME_TYPE;
};

// Throwaway: differential-test getMimeTypeForPath against the real mime-types.
import mime from "mime-types";
import db from "mime-db" with { type: "json" };

const MIME_TYPES_BY_EXTENSION = {
  avif: "image/avif", bmp: "image/bmp", gif: "image/gif",
  ico: "image/vnd.microsoft.icon", jpeg: "image/jpeg", jpg: "image/jpeg",
  png: "image/png", svg: "image/svg+xml", tif: "image/tiff",
  tiff: "image/tiff", webp: "image/webp",
  aac: "audio/aac", flac: "audio/flac", m4a: "audio/mp4", mp3: "audio/mpeg",
  oga: "audio/ogg", ogg: "audio/ogg", wav: "audio/wav",
  mkv: "video/x-matroska", mov: "video/quicktime", mp4: "video/mp4",
  ogv: "video/ogg", webm: "video/webm",
  pdf: "application/pdf",
  canvas: "application/json", css: "text/css", csv: "text/csv",
  html: "text/html", js: "text/javascript", json: "application/json",
  md: "text/markdown", txt: "text/plain", xml: "text/xml",
  yaml: "text/yaml", yml: "text/yaml",
};
const DEFAULT = "application/octet-stream";
const getMimeTypeForPath = (filePath) => {
  const fileName = filePath.split("/").pop() ?? "";
  const i = fileName.lastIndexOf(".");
  if (i <= 0) return DEFAULT;
  return MIME_TYPES_BY_EXTENSION[fileName.slice(i + 1).toLowerCase()] ?? DEFAULT;
};

// Old call site: mime.lookup(path) || "application/octet-stream"
const oldImpl = (p) => mime.lookup(p) || DEFAULT;

// 1. Every extension in our table must match the old behaviour exactly.
console.log("=== (1) disagreements WITHIN our table ===");
let tableBad = 0;
for (const ext of Object.keys(MIME_TYPES_BY_EXTENSION)) {
  const p = `note/asset.${ext}`;
  const [o, n] = [oldImpl(p), getMimeTypeForPath(p)];
  if (o !== n) { console.log(`  .${ext}: old=${o}  new=${n}`); tableBad++; }
}
console.log(tableBad === 0 ? "  none — table is faithful" : `  ${tableBad} disagreements`);

// 2. THE DANGEROUS CLASS: extensions the old impl skipped as text/*, that we
//    now fall back to octet-stream for -> they would start being UPLOADED.
console.log("\n=== (2) extensions that flip from SKIPPED to UPLOADED ===");
const flips = [];
for (const ext of Object.keys(db).flatMap((t) => db[t].extensions ?? [])) {
  const p = `a.${ext}`;
  const o = oldImpl(p), n = getMimeTypeForPath(p);
  if (o.startsWith("text/") && !n.startsWith("text/")) flips.push(`${ext} (${o})`);
}
console.log(flips.length ? flips.join(", ") : "  none");
console.log(`  count: ${flips.length}`);

// 3. Reverse: uploaded before, skipped now -> silent data loss.
console.log("\n=== (3) extensions that flip from UPLOADED to SKIPPED ===");
const rev = [];
for (const ext of Object.keys(MIME_TYPES_BY_EXTENSION)) {
  const p = `a.${ext}`;
  const o = oldImpl(p), n = getMimeTypeForPath(p);
  if (!o.startsWith("text/") && n.startsWith("text/")) rev.push(`${ext}: ${o} -> ${n}`);
}
console.log(rev.length ? rev.join("\n") : "  none");

// 4. Obsidian's documented accepted attachment extensions.
console.log("\n=== (4) Obsidian-accepted attachment extensions ===");
const OBSIDIAN_ATTACHMENTS = [
  "md","canvas","png","webp","jpg","jpeg","gif","bmp","svg","avif",
  "mp3","webm","wav","m4a","ogg","3gp","flac",
  "mp4","ogv","mov","mkv","pdf",
];
for (const ext of OBSIDIAN_ATTACHMENTS) {
  const p = `a.${ext}`;
  const o = oldImpl(p), n = getMimeTypeForPath(p);
  const skipO = o.startsWith("text/"), skipN = n.startsWith("text/");
  const mark = o === n ? "ok  " : skipO === skipN ? "DIFF(same skip)" : "FLIP";
  console.log(`  ${mark} .${ext.padEnd(7)} old=${o.padEnd(26)} new=${n}`);
}

// 5. Path/edge-case parity.
console.log("\n=== (5) path edge cases ===");
for (const p of [
  "archive.tar.png", "folder.v2/asset.png", "noext", ".hidden",
  "UPPER.PNG", "a.JPG", "dir/.config", "trailing.", "sub/dir/file.pdf",
]) {
  const o = oldImpl(p), n = getMimeTypeForPath(p);
  console.log(`  ${o === n ? "ok  " : "DIFF"} ${p.padEnd(22)} old=${o.padEnd(26)} new=${n}`);
}

