if (!target) throw new Error("no Obsidian page target");

const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const send = (method, params = {}) =>
  new Promise((res, rej) => {
    const msgId = ++id;
    pending.set(msgId, { res, rej });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });

ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { res, rej } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
  }
};

await new Promise((res) => (ws.onopen = res));
await send("Runtime.enable");
await send("Page.enable");
// Keep the renderer live even if the window is not focused.
await send("Page.setWebLifecycleState", { state: "active" }).catch(() => {});
await send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});

const scenario = `
(function () {
  var FRONTMATTER_BLOCK = /^---[ \\t]*\\r?\\n([\\s\\S]*?)\\r?\\n?^---[ \\t]*(?:\\r?\\n|$)/m;
  function splitFrontmatter(content) {
    var m = FRONTMATTER_BLOCK.exec(content);
    if (!m || m.index !== 0) return { yaml: null, body: content };
    return { yaml: m[1] == null ? "" : m[1], body: content.slice(m[0].length) };
  }
  var parseYaml = require("obsidian").parseYaml;
  var files = app.vault.getMarkdownFiles();
  return Promise.all(files.map(function (f) {
    return app.vault.cachedRead(f).then(function (content) {
      var s = splitFrontmatter(content);
      var data = null, err = null;
      if (s.yaml !== null) {
