// Throwaway: ground-truth YAML semantics via real notes + metadataCache, then clean up.
import fs from "fs";

const CASES = {
  "date-unquoted": "created: 2026-08-07",
  "date-quoted": 'created: "2026-08-07"',
  "bool-yes": "flag: yes",
  "bool-no": "flag: no",
  "bool-on": "flag: on",
  "bool-true": "flag: true",
  octal: "v: 0777",
  sexagesimal: "v: 12:30",
  "leading-zero": "v: 0123",
  "uuid-nodeTypeId": "nodeTypeId: 7f3a9c12-4b8e-4d21-9a55-1c2e3f4a5b6d",
  "rid-string": "importedFromRid: rid://abc-123",
  norway: "country: NO",
  malformed: "a: [unclosed",
  "empty-value": "key:",
  list: "tags:\n  - one\n  - two",
};

const list = await (await fetch("http://127.0.0.1:9222/json/list")).json();
const t = list.find((x) => x.type === "page" && x.url.includes("obsidian.md"));
const ws = new WebSocket(t.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const send = (method, params = {}) =>
  new Promise((res, rej) => {
    const i = ++id;
    pending.set(i, { res, rej });
    ws.send(JSON.stringify({ id: i, method, params }));
  });
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) {
    const p = pending.get(m.id);
    pending.delete(m.id);
    m.error ? p.rej(new Error(JSON.stringify(m.error))) : p.res(m.result);
  }
};
await new Promise((r) => (ws.onopen = r));
await send("Runtime.enable");

const evaluate = async (expression) => {
  const r = await send("Runtime.evaluate", {
    expression,
    awaitPromise: true,
    returnByValue: true,
  });
  if (r.exceptionDetails)
    throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 400));
  return r.result.value;
};

const DIR = "_dgMobileProbe";
const write = `
(function () {
  var cases = ${JSON.stringify(CASES)};
  var dir = ${JSON.stringify(DIR)};
  return (app.vault.getAbstractFileByPath(dir) ? Promise.resolve() : app.vault.createFolder(dir))
    .catch(function () {})
    .then(function () {
      var names = Object.keys(cases);
      return Promise.all(names.map(function (n, i) {
        var p = dir + "/c" + i + ".md";
        var content = "---\\n" + cases[n] + "\\n---\\nbody text\\n";
        var existing = app.vault.getFileByPath(p);
        return (existing ? app.vault.modify(existing, content)
                         : app.vault.create(p, content)).catch(function (e) { return null; });
      })).then(function () { return names.length; });
    });
